import sys
from rich.console import Console
from rich.file_proxy import FileProxy
import io

def test_isatty_bug():
    console = Console()

    # Case 1: Wrapping sys.stdout (which is a TTY in most interactive shells, 
    # but let's use a mock or just check if it differs)
    # Since we are in a sandbox, sys.stdout might not be a TTY.
    # Let's create a mock file that has isatty() returning True.

    class MockTTY:
        def isatty(self):
            return True
        def write(self, text):
            return len(text)
        def flush(self):
            pass

    tty_file = MockTTY()
    proxy = FileProxy(console, tty_file)

    print(f"tty_file.isatty(): {tty_file.isatty()}")
    print(f"proxy.isatty(): {proxy.isatty()}")

    if proxy.isatty() != tty_file.isatty():
        print("BUG FOUND: proxy.isatty() did not proxy to tty_file.isatty()")
    else:
        print("No bug found: proxy.isatty() proxied correctly.")

if __name__ == "__main__":
    test_isatty_bug()

